concept.cypher:
CALL {
  MATCH (c:Commit)
  WHERE c.sha IS NOT NULL
  WITH c.sha AS sha, collect(c) AS nodes
  WHERE size(nodes) > 1
  CALL {
    // Keep the copy that carries the most detail: the git-clone copy records
    // CONTAINS_CHANGE edges, the GitHub-API copy usually does not. Ties are
    // deterministic by elementId so the outcome is scan-order independent.
    WITH nodes
    UNWIND nodes AS n
    OPTIONAL MATCH (n)-[:CONTAINS_CHANGE]->(ch)
    WITH n, count(ch) AS changes
    ORDER BY changes DESC, elementId(n) ASC
    RETURN collect(n) AS ranked
  }
  // mergeRels:false re-points every relationship onto the survivor without
  // folding parallels (same policy and reason as maven-artifact-identity).
  CALL apoc.refactor.mergeNodes(ranked, {properties: 'discard', mergeRels: false}) YIELD node
  RETURN count(node) AS mergedCommits
}
RETURN mergedCommits
